//#region src/server/operation-token.d.ts
export type OperationLane = "hmr" | "navigation" | "prefetch" | "refresh" | "server-action" | "traverse";
export type OperationToken = {
  operationId: number;
  lane: OperationLane;
  navigationId: number;
  baseVisibleCommitVersion: number;
  graphVersion: string | null;
  deploymentVersion: string | null;
  targetSnapshotFingerprint: string;
  cacheVariantFingerprint?: string;
};
declare const verifiedOperationTokenBrand: unique symbol;
export type VerifiedOperationToken = OperationToken & {
  readonly [verifiedOperationTokenBrand]: true;
};
export type OperationTokenAuthority = {
  activeNavigationId: number;
  visibleCommitVersion: number;
  graphVersion: string | null;
  installedCacheVariantFingerprint: string | null;
};
type OperationTokenDimension = "navigation" | "visibleCommit" | "graphVersion" | "cacheVariant";
export type OperationTokenRejectionReason = "staleNavigation" | "staleVisibleCommit" | "graphVersionMismatch" | "graphVersionMissing" | "cacheVariantMismatch" | "cacheVariantMissing";
export type OperationTokenVerdict = {
  readonly authorized: true;
  readonly token: VerifiedOperationToken;
} | {
  readonly authorized: false;
  readonly reason: OperationTokenRejectionReason;
};
export type OperationTokenVerificationPolicy = {
  check: readonly OperationTokenDimension[];
  require: readonly OperationTokenDimension[];
};
export declare function verifyOperationToken(token: OperationToken, authority: OperationTokenAuthority, policy: OperationTokenVerificationPolicy): OperationTokenVerdict;
export declare function verifyOperationTokenForCommit(token: OperationToken, authority: Pick<OperationTokenAuthority, "activeNavigationId" | "visibleCommitVersion">): OperationTokenVerdict;
export declare function verifyOperationTokenForCacheReuse(token: OperationToken, authority: Pick<OperationTokenAuthority, "graphVersion" | "installedCacheVariantFingerprint">): OperationTokenVerdict;
//#endregion